qa=np.array([m.joint(f'robot0_joint{i}').qposadr[0] for i in range(1,8)]);dv=np.array([m.joint(f'robot0_joint{i}').dofadr[0] for i in range(1,8)]);lim=np.array([m.joint(f'robot0_joint{i}').range for i in range(1,8)])
def act(q=None,bx=0,by=0,mode=-1,torso=.44,grip=-1):
 a=s.initial_command();
 if q is not None:a[:7]=q
 a[7]=grip;a[8]=bx;a[9]=by;a[11]=torso;a[12]=mode;return a
for _ in range(30):s.step(act(torso=.44))
for _ in range(60):s.step(act(bx=.6,by=-.3,mode=1,torso=.44))
print('start eef',d.site_xpos[site].round(3),'base',d.xpos[baseid].round(3),'tor',d.qpos[tor])
sc=mujoco.MjData(m);sc.qpos[:]=d.qpos;sc.qvel[:]=d.qvel;mujoco.mj_forward(m,sc);R0=sc.site_xmat[site].reshape(3,3).copy();Rgoal=Rotation.from_rotvec([0,np.deg2rad(30),0]).as_matrix()@R0

def solve(p,seed,R=None):
 q=seed.copy();p=np.array(p)
 for _ in range(500):
  sc.qpos[qa]=q;mujoco.mj_forward(m,sc);ep=p-sc.site_xpos[site].copy()
  if R is None:
   if np.linalg.norm(ep)<.001:break
   jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv));mujoco.mj_jacSite(m,sc,jp,jr,site);J=jp[:,dv];dq=J.T@np.linalg.solve(J@J.T+.0003*np.eye(3),ep)+.008*(seed-q)
  else:
   er=Rotation.from_matrix(R@sc.site_xmat[site].reshape(3,3).T).as_rotvec()
   if np.linalg.norm(ep)<.002 and np.linalg.norm(er)<.03:break
   jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv));mujoco.mj_jacSite(m,sc,jp,jr,site);J=np.vstack([jp[:,dv],.6*jr[:,dv]]);e=np.r_[ep,.6*er];dq=J.T@np.linalg.solve(J@J.T+.0005*np.eye(6),e)+.002*(seed-q)
  mx=max(abs(dq));dq*=min(1,.055/mx);q=np.clip(q+dq,lim[:,0]+.002,lim[:,1]-.002)
 sc.qpos[qa]=q;mujoco.mj_forward(m,sc);return q,sc.site_xpos[site].copy(),np.linalg.norm(p-sc.site_xpos[site].copy())
def contacts():
 out=[]
